package repository

import (
	"gau-kanban-service/entity"
	"gorm.io/gorm"
)

type ChecklistRepository struct {
	DB *gorm.DB
}

func NewChecklistRepository(db *gorm.DB) *ChecklistRepository {
	return &ChecklistRepository{
		DB: db,
	}
}

func (r *ChecklistRepository) Create(checklist *entity.Checklist) error {
	return r.DB.Create(checklist).Error
}

func (r *ChecklistRepository) GetByTicketID(ticketID string) ([]entity.Checklist, error) {
	var checklists []entity.Checklist
	err := r.DB.Where("ticket_id = ?", ticketID).Order("position ASC").Find(&checklists).Error
	return checklists, err
}

func (r *ChecklistRepository) GetByID(id string) (*entity.Checklist, error) {
	var checklist entity.Checklist
	err := r.DB.Where("id = ?", id).First(&checklist).Error
	if err != nil {
		return nil, err
	}
	return &checklist, nil
}

func (r *ChecklistRepository) Update(checklist *entity.Checklist) error {
	return r.DB.Save(checklist).Error
}

func (r *ChecklistRepository) Delete(id string) error {
	return r.DB.Where("id = ?", id).Delete(&entity.Checklist{}).Error
}

func (r *ChecklistRepository) DeleteByTicketID(ticketID string) error {
	return r.DB.Where("ticket_id = ?", ticketID).Delete(&entity.Checklist{}).Error
}

func (r *ChecklistRepository) UpdatePosition(id string, position int) error {
	return r.DB.Model(&entity.Checklist{}).Where("id = ?", id).Update("position", position).Error
}

func (r *ChecklistRepository) GetMaxPosition(ticketID string) (int, error) {
	var maxPosition int
	err := r.DB.Model(&entity.Checklist{}).Where("ticket_id = ?", ticketID).Select("COALESCE(MAX(position), 0)").Scan(&maxPosition).Error
	return maxPosition, err
}
